// The one error type this library lets out of its deserializers.
//
// nlohmann/json throws json::parse_error, json::type_error, json::out_of_range;
// yaml-cpp throws YAML::ParserException, YAML::BadConversion, ...; your binary
// decoder has failure modes of its own. A caller should not need to know any
// of that: whatever went wrong while turning bytes into a SensorData comes out
// as ParseError, with a message a human can act on.
//
// DO NOT EDIT this file.

#ifndef AIS2203_PARSE_ERROR_HPP
#define AIS2203_PARSE_ERROR_HPP

#include <stdexcept>

namespace ais2203 {

class ParseError : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;
};

} // namespace ais2203

#endif // AIS2203_PARSE_ERROR_HPP
